import streamlit as st

st.title("Cadastro de Produtos")

if "produtos" not in st.session_state:
    st.session_state.produtos = []

with st.container(border=True):
    nome = st.text_input("Produto")
    qtd = st.number_input("Quantidade", min_value=0, step=1)
    if st.button("Adicionar"):
        if nome:
            st.session_state.produtos.append({"Produto": nome, "Quantidade": qtd})
            st.success(f"{nome} adicionado!")
        else:
            st.error("Informe o nome do produto.")

for i, p in enumerate(st.session_state.produtos):
    c1, c2 = st.columns([0.8, 0.2])
    c1.write(f"{p['Produto']}: {p['Quantidade']}")
    if c2.button("Excluir", key=f"exc_{i}"):
        st.session_state.produtos.pop(i)
        st.rerun()

