if "compras" not in st.session_state:
    st.session_state.compras = []

item = st.text_input("Item")
if st.button("Adicionar"):
    if item:
        st.session_state.compras.append(item)
    else:
        st.warning("Digite um item.")

for i, c in enumerate(st.session_state.compras, start=1):
    st.write(f"{i}. {c}")

for i, c in enumerate(st.session_state.compras):
    col1, col2 = st.columns([0.8, 0.2])
    col1.write(f"{i + 1}. {c}")
    if col2.button("Remover", key=f"rem_{i}"):
        st.session_state.compras.pop(i)
        st.rerun()
